let studySequence=0,studyController;
const studyNumber=(v,unit='%')=>typeof v==='number'&&Number.isFinite(v)?v.toFixed(2)+unit:'—';
async function loadStudy(){const sequence=++studySequence;studyController?.abort();studyController=new AbortController();$('study-status').textContent='正在计算历史技术信号…';$('study-results').innerHTML='';$('study-method').textContent='';const activeController=studyController;const timer=setTimeout(()=>activeController.abort(),25000);try{const res=await fetch('/api/study?symbol='+encodeURIComponent($('symbol').value)+'&horizon='+$('horizon').value,{signal:studyController.signal});if(!res.ok)throw Error('failed');const d=await res.json();if(sequence!==studySequence)return;if(!d.available){$('study-status').textContent=d.message;return;}$('study-status').textContent=`${d.symbol} · ${d.start} 至 ${d.end} · ${d.bars} 根日线 · ${d.horizon} 交易日观察窗口`;
 $('study-results').innerHTML=['dip','trend'].map(path=>{const r=d.results[path];return `<article class="study-card"><h3>${path==='dip'?'回撤企稳':'趋势技术候选'}</h3><p class="study-label">${esc(r.sampleStatus)}</p><div class="study-metrics"><div><small>完成样本</small><strong>${r.count}</strong></div><div><small>平均净收益</small><strong>${studyNumber(r.meanReturn)}</strong></div><div><small>相对SOXX</small><strong>${studyNumber(r.meanExcess,' 个百分点')}</strong></div><div><small>最差不利变动</small><strong>${studyNumber(r.worstMAE)}</strong></div></div><p class="muted">${r.pending} 个待观察完成 · ${r.skipped} 个因数据不全跳过${r.positive===null?' · 少于10个完成样本，不展示正收益比例':' · 正收益样本比例 '+r.positive.toFixed(0)+'%'}</p><details><summary>查看逐笔记录</summary>${r.events.length?`<div class="table-scroll"><table class="watch-table"><thead><tr><th>信号日期</th><th>进入 → 退出</th><th>净收益</th><th>相对SOXX</th><th>不利变动</th></tr></thead><tbody>${r.events.slice().reverse().map(e=>`<tr><td>${esc(e.signal)}</td><td>${esc(e.entry)} → ${esc(e.exit)}</td><td>${studyNumber(e.net)}</td><td>${studyNumber(e.excess,' pp')}</td><td>${studyNumber(e.mae)}</td></tr>`).join('')}</tbody></table></div>`:'<p>这段历史内没有已完成的非重叠样本。</p>'}</details></article>`;}).join('');$('study-method').textContent=d.method;}catch(e){if(sequence===studySequence)$('study-status').textContent='历史结果暂时无法获取，请重试。';}finally{clearTimeout(timer);}}
$('symbol').addEventListener('change',loadStudy);$('horizon').addEventListener('change',loadStudy);$('refresh-study').onclick=loadStudy;loadStudy();
